<?phpnamespace app\common\model;/** * 店员模型 */class ShopClerk extends BaseModel{    // 定义表名    protected $name = 'shop_clerk';    // 定义主键    protected $pk = 'shop_clerk_id';    // 追加字段    protected $append = [];    /**     * 身份     */    public function getStatusAttr($value)    {        $status = [10 => '店员', 20 => '店长'];        return ['text' => $status[$value], 'value' => $value];    }    /**     * 获取列表     */    public function getList(string $search = '',$page=true,$status=10)    {        //筛选条件        $filter = [];        if(!empty($search)){            //判断是否是手机号            if(is_phone($search)){                $filter['phone'] = $search;            }else{                $filter['linkman'] = $search;            }        }        $status > 0 && $filter['status'] = $status;        // 排序规则        $sort = ['shop_clerk_id' => 'desc'];        // 执行查询        $model =  $this->where($filter)            ->order($sort);        if($page){            return $model->paginate(['list_rows'=>15,'query' => request()->param()]);        }else{            return $model->select();        }    }    /**     * 添加     */    public function add(array $data)    {        if(!is_phone($data['phone'])){            $this->error = '手机号码格式错误';            return false;           }        //验证手机号是否存在        if($this->withoutGlobalScope()->where(['phone' => $data['phone']])->count()){            $this->error = '手机号码被占用';            return false;        }        $data['password'] = hema_hash($data['phone']);        return $this->save($data);    }    /**     * 编辑     */    public function edit(array $data)    {        //如果修改了手机号码，密码重置为新手机号码        if(isset($data['phone']) and $this->phone != $data['phone']){			if(!is_phone($data['phone'])){                $this->error = '手机号码格式错误';                return false;               }            if($this->withoutGlobalScope()->where(['phone' => $data['phone']])->count()){                $this->error = '手机号码被占用';                return false;            }            $data['password'] = hema_hash($data['phone']);        }        return $this->save($data) !== false;    }    /**     * 删除     */    public function remove()    {        return $this->delete();    }		/**	 * 更新当前管理员信息	 */	public function renew(array $data)	{  	    if (strlen($data['password']) < 6) {	        $this->error = '密码长度不足6位';	        return false;	    }	    if ($data['password'] != $data['password_confirm']) {	        $this->error = '两次密码输入不一致';	        return false;	    }	    $data['password'] = hema_hash($data['password']);	    // 更新管理员信息	    return $this->save($data) !== false;	}}